{
 "command": "cat scripts/backfill_tax.py && ls scripts",
 "description": "Show backfill script and scripts dir"
}

{
 "command": "cat docs/ops/backfills.md 2>&1; echo \"---\"; echo \"TZ=${TZ:-<unset>} DATABASE_URL=${DATABASE_URL:+<set>} BACKFILL_BATCH=${BACKFILL_BATCH:-<unset>}\"",
 "description": "Read backfill docs and check env vars"
}

{
 "command": "TZ=UTC python scripts/backfill_tax.py --month 2026-09 --batch-size 500; echo \"exit=$?\"",
 "description": "Run September tax backfill with UTC and safe batch size"
}

{
 "id": "01a10830-bf67-7df1-ae1a-49c475da7c1f",
 "evidence": "scripts/backfill_tax.py's docstring says \"Recompute tax_cents for finalized invoices of one month\", and docs/ops/backfills.md documents running it as an ops procedure. The memory says tax_cents \"is never recomputed after finalization\". Either the backfill is a sanctioned exception the memory doesn't mention, or the script goes against the rule. Needs a human to decide which.",
 "source_file": "scripts/backfill_tax.py"
}
